#!/usr/bin/env python3
import hashlib,json,re,subprocess,sys
from pathlib import Path
assert sys.flags.isolated and sys.flags.no_site
root=Path(__file__).resolve().parents[2];repo=root.parents[1];p=root/'research/nine-sharing-sign14-positive74-object-predecessor-check';sha=lambda q:hashlib.sha256(q.read_bytes()).hexdigest()
assert sha(p/'run.py')=='4c784ee73f3b23c95bdf45d7ece6ad7dd70d6c025bab8cc3451b9188945a52ff' and sha(p/'source-manifest.json')=='20abf617a1fd5a0bfddbfcf0bf2461c7a6534af9efcbe45d6e35034f4b079fcc'
e,=json.loads((p/'source-manifest.json').read_text())['rows'];n='Sign14Positive74ObjectPredecessor';q=p/'src/DiophantineConsistency'/(n+'.lean');s=q.read_text();imports=['DiophantineConsistency.Sign14Positive74ObjectGuard','DiophantineConsistency.IPRAPredReconstruct','DiophantineConsistency.IPRANativeAtomStability','DiophantineConsistency.IPRATheoryInstantiation','Foundation.Meta.IntProver'];assert e['module']=='DiophantineConsistency.'+n and e['imports']==imports and sha(q)==sha(repo/e['source'])==e['source_sha256']=='78038b8875914eda63bd2b01c620afbcfb93f8694d64961d97612071ff4d9f6c' and re.findall(r'^import ([A-Za-z0-9_.]+)$',s,re.M)==imports and not re.search(r'(?m)^\s*(axiom|opaque|partial)\b|\b(sorry|admit|native_decide)\b',s)
for z in ('def reconstructionOpen (x : Term language ℕ)','extended nativeTheory ⊢! (eqAt x zero ⋎ eqAt x (succ (pred x)))','instantiateTheory (T := nativeTheory) IPRAPredReconstruct.reconstruct','Classical.choice IPRAPredReconstruct.reconstruction','def nonzeroReconstructionOpen (x : Term language ℕ)','extended nativeTheory ⊢! (∼eqAt x zero 🡒 eqAt x (succ (pred x)))','int_prover','exact t ⨀ reconstructionOpen x'):assert z in s
old=(root/'Lean/DiophantineConsistency/IPRAPredReconstruct.lean').read_text();assert 'def reconEq : Semisentenceᵢ language 1 := .rel .eq ![#0, .func .succ (fun _ => .func predCode (fun _ => #0))]' in old and 'def reconstruct : Semisentenceᵢ language 1 := IPRAZeroDecidable.zeroEq ⋎ reconEq' in old and 'theorem reconstruction : nativeTheory ⊢ ∀⁰ reconstruct' in old
subprocess.run([sys.executable,'-I','-S','-B',str(root/'reviews/nine-sharing-sign14-positive74-object-guard-terminal-independent/check.py')],capture_output=True,check=True,timeout=180)
x=subprocess.run([sys.executable,'-I','-S','-B',str(p/'framework-survey.py')],capture_output=True,text=True,check=True,timeout=180);v=json.loads(x.stdout);assert not x.stderr and v['status']=='PASS' and all(k in v['observed'] for k in ('IPRAPredReconstruct','IPRANativeAtomStability','IPRATheoryInstantiation','IntProver'))
r=(p/'run.py').read_text();assert "'-M3600'" in r and "LEAN_NUM_THREADS='1'" in r and "'-j1'" in r and 'rss_limit=4*1024**3,mem_floor=10*1024**3,seconds=120,interval=.1' in r and 'direct producer binding' in r
x=subprocess.run([sys.executable,'-I','-S','-B',str(p/'run.py'),'--preflight'],capture_output=True,text=True,check=True,timeout=180);assert not x.stderr and json.loads(x.stdout)['status']=='PASS_NO_LEAN_PREFLIGHT'
print(json.dumps({'status':'PASS_PRELAUNCH','scope':'open native predecessor reconstruction and nonzero implication only; historical object pins not source-authenticated'},indent=2))
